mkdir -p lib test && cat > package.json <<'EOF'
{
  "name": "set-proto",
  "version": "0.1.0",
  "description": "Cross-platform helper to set the prototype of an object at runtime",
  "main": "lib/index.js",
  "types": "lib/index.d.ts",
  "files": [
    "lib"
  ],
  "scripts": {
    "test": "node --test"
  },
  "keywords": [
    "prototype",
    "setPrototypeOf",
    "__proto__",
    "polyfill"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=18"
  }
}
EOF
cat > lib/index.js <<'EOF'
'use strict';

/**
 * Set the prototype of `obj` to `proto` and return `obj`.
 *
 * Resolution order:
 *   1. Native Object.setPrototypeOf (ES2015+, all modern runtimes).
 *   2. The `__proto__` setter (legacy engines that support it).
 *   3. Copy own properties from `proto` onto `obj` (last resort; `obj` will
 *      not observe later changes to `proto`, and `instanceof` won't work).
 */
var setPrototypeOf = Object.setPrototypeOf ||
  ({ __proto__: [] } instanceof Array ? setProtoOf : mixinProperties);

function setProtoOf(obj, proto) {
  obj.__proto__ = proto;
  return obj;
}

function mixinProperties(obj, proto) {
  for (var prop in proto) {
    if (!Object.prototype.hasOwnProperty.call(obj, prop)) {
      obj[prop] = proto[prop];
    }
  }
  return obj;
}

module.exports = setPrototypeOf;
module.exports.setProtoOf = setProtoOf;
module.exports.mixinProperties = mixinProperties;
EOF
cat > lib/index.d.ts <<'EOF'
declare function setPrototypeOf<T extends object>(obj: T, proto: object | null): T;

declare namespace setPrototypeOf {
  function setProtoOf<T extends object>(obj: T, proto: object | null): T;
  function mixinProperties<T extends object>(obj: T, proto: object): T;
}

export = setPrototypeOf;
EOF
cat > test/index.test.js <<'EOF'
'use strict';

const test = require('node:test');
const assert = require('node:assert');
const setPrototypeOf = require('..');
const { setProtoOf, mixinProperties } = setPrototypeOf;

test('uses native Object.setPrototypeOf when available', () => {
  assert.strictEqual(setPrototypeOf, Object.setPrototypeOf);
});

for (const [name, fn] of [['default', setPrototypeOf], ['setProtoOf', setProtoOf]]) {
  test(`${name}: sets the prototype and returns the object`, () => {
    const proto = { greet() { return 'hi'; } };
    const obj = {};
    assert.strictEqual(fn(obj, proto), obj);
    assert.strictEqual(Object.getPrototypeOf(obj), proto);
    assert.strictEqual(obj.greet(), 'hi');
  });

  test(`${name}: supports instanceof`, () => {
    class Foo {}
    assert.ok(fn({}, Foo.prototype) instanceof Foo);
  });
}

test('mixinProperties: copies props without overwriting own props', () => {
  const obj = mixinProperties({ a: 1 }, { a: 2, b: 3 });
  assert.deepStrictEqual(obj, { a: 1, b: 3 });
});
EOF
cat > .gitignore <<'EOF'
node_modules/
*.log
coverage/
EOF
cat > README.md <<'EOF'
# set-proto

Cross-platform helper to set an object's prototype at runtime.

```js
const setPrototypeOf = require('set-proto');

const obj = setPrototypeOf({}, Foo.prototype);
obj instanceof Foo; // true
```

Uses native `Object.setPrototypeOf` when available, falling back to the
`__proto__` setter, and finally to copying properties on very old engines.

## Development

```sh
npm test
```
EOF
npm test 2>&1 | tail -12

